// The Prism reads every example of the specifications its content follows the
// way those specifications say it reads (test/oracle/corpus.json, generated by
// tools/oracle/gen.py from app/specs/oracle/spec.json). Each field the
// reference reader found is compared with the Prism's own reading
// (site/card.mjs readItem with site/read/read.mjs). A field the Prism does not
// yet read right is listed as debt in the oracle spec, which only shrinks: a
// new miss fails, and so does debt that now reads right.
// usage: node --test test/oracle/read.test.mjs
import assert from "node:assert/strict";
import { spawnSync } from "node:child_process";
import { readFileSync } from "node:fs";
import { tmpdir } from "node:os";
import { join } from "node:path";
import test from "node:test";
import { readItem, useReader } from "../../site/card.mjs";
import * as reader from "../../site/read/read.mjs";

useReader(reader);
const { corpus } = JSON.parse(readFileSync("test/oracle/corpus.json", "utf8"));
const spec = JSON.parse(readFileSync("app/specs/oracle/spec.json", "utf8"));
const encoder = new TextEncoder();
const MEDIA = { message: "message", calendar: "calendar", contact: "contactCard" };
const pad = (n, w = 2) => String(n).padStart(w, "0");
const localOf = (ms) => { const d = new Date(ms); return `${pad(d.getFullYear(), 4)}-${pad(d.getMonth() + 1)}-${pad(d.getDate())}T${pad(d.getHours())}:${pad(d.getMinutes())}:${pad(d.getSeconds())}`; };

// What the Prism reads for each field the reference reader found.
function misses(example) {
  const item = readItem({ address: example.id, outcome: "restore", bytes: encoder.encode(example.raw), meta: { about: { media: MEDIA[example.kind], domain: 4, at: 0 } } });
  const out = [];
  const same = (field, want, got) => { if (want !== got) out.push({ id: example.id, field, want, got }); };
  const e = example.expect;
  if ("title" in e) same("title", e.title.replace(/\s+/g, " ").trim(), (item.title ?? "").replace(/\s+/g, " ").trim());
  if ("who" in e) same("who", e.who, item.who);
  if ("at" in e) same("at", e.at, item.at);
  if (e.start && !e.repeats) {
    if ("at" in e.start) same("start", e.start.at, item.at);
    else if ("date" in e.start) same("start", e.start.date, Number.isFinite(item.at) ? localOf(item.at).slice(0, 10) : String(item.at));
    else if ("local" in e.start && !("zone" in e.start)) same("start", e.start.local, Number.isFinite(item.at) ? localOf(item.at) : String(item.at));
  }
  if (e.start && "date" in e.start) same("allDay", true, item.allDay);
  return out;
}

const key = (m) => `${m.id} ${m.field}`;
const found = corpus.flatMap(misses);
const debt = new Map((spec.debt ?? []).map((d) => [key(d), d]));

test("the corpus is what the pinned specifications give, read by the reference reader", () => {
  const run = spawnSync("python3", ["-I", "tools/oracle/gen.py", "--check", "--cache", join(tmpdir(), "prism-oracle")], { encoding: "utf8" });
  assert.equal(run.status, 0, run.stderr || run.stdout);
});

test("the corpus is the specifications' own examples, with something to compare", () => {
  assert.ok(corpus.length >= 50, `only ${corpus.length} examples`);
  for (const kind of ["message", "calendar", "contact"]) assert.ok(corpus.some((c) => c.kind === kind && Object.keys(c.expect).length), `no ${kind} example with a reading`);
});

test("the Prism reads every example as its specification does, beyond the listed debt", () => {
  const fresh = found.filter((m) => !debt.has(key(m)));
  assert.deepEqual(fresh, [], `the Prism now misreads these: fix the reading, or list each under "debt" in app/specs/oracle/spec.json with why`);
  const gone = [...debt.keys()].filter((k) => !found.some((m) => key(m) === k));
  assert.deepEqual(gone, [], `these now read right: remove them from "debt" in app/specs/oracle/spec.json so they stay right`);
});
